async () => {
  const parse = async (url) => { const h = await (await fetch(url, {credentials:'include'})).text(); const d = new DOMParser().parseFromString(h,'text/html'); return {counts:[...d.querySelectorAll('.subsubsub li')].map(l=>l.textContent.trim()), rows:[...d.querySelectorAll('#the-list tr')].map(r=>r.id+': '+(r.querySelector('.row-title, strong')?.textContent.trim()))}; };
  const all = await parse('/wp-admin/edit.php?post_type=post&post_status=all');
  const trash = await parse('/wp-admin/edit.php?post_type=post&post_status=trash');
  const restRes = await fetch('/?rest_route=/wp/v2/posts&per_page=100', {credentials:'omit'});
  const restTxt = await restRes.text();
  let rest; try { rest = JSON.parse(restTxt).map(p=>p.id+': '+p.title.rendered); } catch(e) { rest = 'non-JSON '+restRes.status+': '+restTxt.slice(0,200); }
  const pub = {};
  for (const id of [7,8,9]) { const r = await fetch('/?p='+id, {credentials:'omit'}); const t = await r.text(); pub[id] = r.status + ' ' + (new DOMParser().parseFromString(t,'text/html').title); }
  return {all, trash, rest, pub};
}

